import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"46、【升】 巽下坤上","description":"橫渠易說 - 46、【升】 巽下坤上","frontmatter":{"title":"46、【升】 巽下坤上","description":"橫渠易說 - 46、【升】 巽下坤上"},"headers":[],"relativePath":"classics/hengqu/048.md","filePath":"classics/hengqu/048.md"}'),l={name:"classics/hengqu/048.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_46、【升】-巽下坤上" tabindex="-1">46、【升】 巽下坤上 <a class="header-anchor" href="#_46、【升】-巽下坤上" aria-label="Permalink to “46、【升】 巽下坤上”">​</a></h1><h3 id="彖曰-柔以時升-巽而順-剛中而應-是以大亨。-用見大人勿恤-有慶也-南征吉-志行也。" tabindex="-1">彖曰：柔以時升，巽而順，剛中而應，是以大亨。“用見大人勿恤”，有慶也，“南征吉”，志行也。 <a class="header-anchor" href="#彖曰-柔以時升-巽而順-剛中而應-是以大亨。-用見大人勿恤-有慶也-南征吉-志行也。" aria-label="Permalink to “彖曰：柔以時升，巽而順，剛中而應，是以大亨。“用見大人勿恤”，有慶也，“南征吉”，志行也。”">​</a></h3><h3 id="象曰-地中生木-升-君子以順德積小以高大。" tabindex="-1">象曰：地中生木，升，君子以順德積小以高大。 <a class="header-anchor" href="#象曰-地中生木-升-君子以順德積小以高大。" aria-label="Permalink to “象曰：地中生木，升，君子以順德積小以高大。”">​</a></h3><p>萃者聚也，聚而上者謂之升，故受之以升。 乾之九二利見大人而以時之止，升之九二有六五配合之慶，故可見大人之德，南征而勿恤也。</p><h3 id="初六-允升-大吉。-象曰-允升大吉-上合志也。" tabindex="-1">初六，允升，大吉。 象曰：“允升大吉”，上合志也。 <a class="header-anchor" href="#初六-允升-大吉。-象曰-允升大吉-上合志也。" aria-label="Permalink to “初六，允升，大吉。 象曰：“允升大吉”，上合志也。”">​</a></h3><p>允，信也。自信於己，與上合志而升。</p><h3 id="九二-孚乃利用禴-無咎。-象曰-九二之孚-有喜也。" tabindex="-1">九二，孚乃利用禴，無咎。 象曰：九二之孚，有喜也。 <a class="header-anchor" href="#九二-孚乃利用禴-無咎。-象曰-九二之孚-有喜也。" aria-label="Permalink to “九二，孚乃利用禴，無咎。 象曰：九二之孚，有喜也。”">​</a></h3><p>與萃六二同。</p><h3 id="九三-升虛邑。-象曰-升虛邑-無所疑也。" tabindex="-1">九三，升虛邑。 象曰：“升虛邑”，無所疑也。 <a class="header-anchor" href="#九三-升虛邑。-象曰-升虛邑-無所疑也。" aria-label="Permalink to “九三，升虛邑。 象曰：“升虛邑”，無所疑也。”">​</a></h3><p>上皆陰柔，往無所疑。</p><h3 id="六四-王用亨於岐山-吉無咎。-象曰-王用亨於岐山-順事也。" tabindex="-1">六四，王用亨於岐山，吉無咎。 象曰：“王用亨於岐山”，順事也。 <a class="header-anchor" href="#六四-王用亨於岐山-吉無咎。-象曰-王用亨於岐山-順事也。" aria-label="Permalink to “六四，王用亨於岐山，吉無咎。 象曰：“王用亨於岐山”，順事也。”">​</a></h3><h3 id="六五-貞吉升階。-象曰-貞吉升階-大得志也。" tabindex="-1">六五，貞吉升階。 象曰：“貞吉升階”，大得志也。 <a class="header-anchor" href="#六五-貞吉升階。-象曰-貞吉升階-大得志也。" aria-label="Permalink to “六五，貞吉升階。 象曰：“貞吉升階”，大得志也。”">​</a></h3><p>柔中極尊，不拒來者，使物皆階己而升，正而且吉，志宜大獲也。易所謂“得志”者，聖賢獲其願欲。得臣無家，堯之志也，貞吉升階，舜之志也。</p><h3 id="上六-冥升-利於不息之貞。-象曰-冥升在上-消不富也。" tabindex="-1">上六，冥升，利於不息之貞。 象曰：冥升在上，消不富也。 <a class="header-anchor" href="#上六-冥升-利於不息之貞。-象曰-冥升在上-消不富也。" aria-label="Permalink to “上六，冥升，利於不息之貞。 象曰：冥升在上，消不富也。”">​</a></h3>',14)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
